-- Reads the running mod's public metadata and versions, and writes through its log.
local check = require("check")
check.plan("metadata", "own_version", "missing", "invalid", "log")
local listening
listening = time.on_step(function()
    listening:cancel()
    check.run("metadata", function()
        check.equal(check.result("ok", "its ID", mod.id()), "check.mods", "the manifest's ID")
        check.equal(check.result("ok", "its name", mod.name()), "The check of mods", "the manifest's name")
        check.equal(check.result("ok", "its version", mod.version()), "1.0.0", "the manifest's version")
    end)
    check.run("own_version", function()
        check.equal(check.result("ok", "the running mod's version", mod.version_of("check.mods")), mod.version(), "both public ways agree")
    end)
    check.run("missing", function()
        check.result("not_found", "a mod that is not installed", mod.version_of("check.mod.not-installed"))
    end)
    check.run("invalid", function()
        check.result("not_found", "an empty ID", mod.version_of(""))
    end)
    check.run("log", function()
        check.result("ok", "writing its own line", mod.log("the public mods log check"))
    end)
end)
